Predict this JavaScript program under standard ECMAScript promise job semantics. Promise reaction jobs and queueMicrotask jobs run FIFO; jobs enqueued during draining run before the timer phase. Assume no I/O or other tasks. Return exactly one JSON object with fields log and x, where log is the exact string array after the timer callback finishes and x is the final integer state.x.
const log = [], state = { x: 0 };
async function inner() {
  log.push("inner:start");
  state.x += 1;
  await null;
  log.push("inner:resume:" + state.x);
  return "I";
}
async function outer() {
  log.push("outer:start");
  const pending = inner();
  Promise.resolve().then(() => {
    state.x += 2;
    log.push("then:add:" + state.x);
    queueMicrotask(() => log.push("then:nested:" + state.x));
  });
  queueMicrotask(() => {
    state.x *= 3;
    log.push("micro:multiply:" + state.x);
  });
  try {
    const value = await pending;
    log.push("outer:await:" + value + ":" + state.x);
    return "O";
  } finally {
    log.push("outer:finally:" + state.x);
  }
}
const result = outer();
